# --------------------------------------------- hand-written ids to preserve
HAND_IDS = {
    # hafez (27)
    2130,2132,2133,2134,2137,2139,2140,2148,2155,2166,2170,2200,2213,2250,2260,
    2263,2272,2281,2293,2295,2303,2312,2384,2447,2498,2599,2622,
    # khayyam (16)
    1119,1122,1123,1126,1130,1137,1142,1163,1165,1184,1204,1208,1210,1239,1249,1261,
    # saadi (21)
    9323,9324,9330,9363,9366,9590,10209,41309,41407,41303,
    41293,10215,10256,10286,10311,10339,10354,10369,10398,10413,10435,
    # rumi (8)
    7893,8095,3065,3187,3998,4027,4843,7901,
}

def gen(pid, poet, coll, tag):
    tag = tag if tag in MESSAGES else "wisdom"
    poet_fa = POET_FA.get(poet, "حافظ")
    form = FORM.get(coll, "قطعه")
    opener = OPENERS[pid % len(OPENERS)].format(form=form, poet=poet_fa, theme=THEME[tag])
    message = MESSAGES[tag][(pid // 7) % len(MESSAGES[tag])]
    closer = CLOSERS[tag][(pid // 3) % len(CLOSERS[tag])]
    if pid % 10 < 3:
        return f"{message} {closer}"
    return f"{opener} {message} {closer}"

def main():
    for name in ["hafez", "khayyam", "saadi", "rumi"]:
        path = f"{CORPUS}/{name}.json"
        data = json.load(open(path, encoding="utf-8"))
        rewritten = new_hand = preserved = 0
        for p in data:
            pid = p["id"]
            if pid in HAND_IDS:
                preserved += 1
                continue
            first = (p["verses"][0]["first"] if p["verses"] else "")
            hit = next((h for h in NEW_HAND if lkey(h[0]) in lkey(first)), None)
            if hit:
                p["themeTag"] = hit[1]
                p["tafsir"] = hit[2]
                new_hand += 1
            else:
                p["tafsir"] = gen(pid, p["poet"], p["collection"], p.get("themeTag", "wisdom"))
                rewritten += 1
        json.dump(data, open(path, "w"), ensure_ascii=False, indent=1)
        print(f"{name}: {len(data)} poems | preserved(hand)={preserved} | new-hand={new_hand} | rewritten={rewritten}")

    # report any NEW_HAND that never matched
    hafez = json.load(open(f"{CORPUS}/hafez.json", encoding="utf-8"))
    firsts = [lkey(p["verses"][0]["first"]) for p in hafez if p["verses"]]
    for sub, _, _ in NEW_HAND:
        if not any(lkey(sub) in f for f in firsts):
            print("  UNMATCHED famous ghazal:", sub)

    print("\n=== samples ===")
    shown = 0
    for p in hafez:
        if p["id"] not in HAND_IDS and not any(lkey(h[0]) in lkey(p["verses"][0]["first"]) for h in NEW_HAND):
            print(f"#{p['id']} [{p['themeTag']}] {p['verses'][0]['first'][:36]}\n   {p['tafsir']}\n")
            shown += 1
            if shown == 3: break
    kh = json.load(open(f"{CORPUS}/khayyam.json", encoding="utf-8"))
    for p in kh:
        if p["id"] not in HAND_IDS:
            print(f"#{p['id']} [{p['themeTag']}] {p['verses'][0]['first'][:36]}\n   {p['tafsir']}\n")
            break

if __name__ == "__main__":
    main()
